async function mockGoogle(ctx, email) {
  // 0.9.10: report / approval proxy actions are mocked (the chat traffic is untouched).
  globalThis.__repPosts = []; await ctx.route(/script\.google\.com\/macros/, async r => { const b = r.request().postData() || ''; let j = {}; try { j = JSON.parse(b); } catch { /* not JSON */ } if (!j.action) return r.fallback(); globalThis.__repPosts.push(j); return r.fulfill({ contentType: 'application/json', body: JSON.stringify({ status: 200, body: j.action === 'listReports' ? { reports: [{ id: 'srv1', category: 'harmful', kind: 'smarty', version: '0.9.10', at: '2026-11-01', answer: 'server copy', question: 'q', note: '' }] } : { ok: true } }) }); });
  await ctx.addInitScript(() => { if (!localStorage.getItem('prvlar-age')) localStorage.setItem('prvlar-age', JSON.stringify({ result: 'adult', checked: '2026-10-31' })); });   // age is tested separately (Age steps)
  await ctx.route('https://accounts.google.com/gsi/client', r => r.fulfill({ contentType: 'text/javascript', body: `window.google={accounts:{oauth2:{initTokenClient:o=>({requestAccessToken(){setTimeout(()=>o.callback({access_token:'tok-test',expires_in:3600,scope:'https://www.googleapis.com/auth/drive.appdata openid email profile'}),50)}}),hasGrantedAllScopes:(r,...s)=>s.every(x=>(r.scope||'').includes(x)),revoke(t,cb){cb&&cb()}}}};` }));
  await ctx.route('https://www.googleapis.com/oauth2/v3/userinfo', r => r.fulfill({ json: { email, name: 'Test Owner', picture: '' } }));
  await ctx.route(/https:\/\/www\.googleapis\.com\/(upload\/)?drive\/v3\/.*/, async r => {
    const u = new globalThis.URL(r.request().url()), m = r.request().method(); if (m === 'POST' || m === 'PATCH') globalThis.__driveWrites = (globalThis.__driveWrites || 0) + 1;
    if (m === 'GET' && u.pathname.endsWith('/files')) { const q = u.searchParams.get('q') || ''; const name = (q.match(/name='([^']+)'/) || [])[1]; return r.fulfill({ json: { files: Object.entries(drive.files).filter(([, f]) => !name || f.name === name).map(([id, f]) => ({ id, name: f.name, size: String(f.body.length), modifiedTime: new Date().toISOString() })) } }); }
    const id = (u.pathname.match(/files\/([^/]+)$/) || [])[1];
    if (m === 'GET' && id) return drive.files[id] ? r.fulfill({ contentType: 'application/json', body: drive.files[id].body }) : r.fulfill({ status: 404, json: {} });
    if (m === 'DELETE' && id) { delete drive.files[id]; return r.fulfill({ status: 204, body: '' }); }
    if (m === 'POST' || m === 'PATCH') { const body = r.request().postData() || ''; const parts = body.split(/--ka[a-z0-9]+/).filter(p => p.includes('\r\n\r\n')); const meta = JSON.parse(parts[0].split('\r\n\r\n')[1]); const content = parts[1].split('\r\n\r\n').slice(1).join('\r\n\r\n').replace(/\r\n$/, '');
      const fid = id || 'f' + (++drive.n); drive.files[fid] = { name: meta.name || drive.files[fid]?.name, body: content }; return r.fulfill({ json: { id: fid, size: String(content.length) } }); }
    return r.fulfill({ status: 400, json: {} });
  });
}
